class MinStack:
    def __init__(self):
        self.vals: list[int] = []
        self.mins: list[int] = []  # mins[i] is the smallest of vals[0], ..., vals[i]

    def push(self, val: int) -> None:
        vals, mins = self.vals, self.mins
        low = val if not mins else min(val, mins[-1])  # viz:compare
        vals.append(val)  # viz:push
        mins.append(low)

    def pop(self) -> None:
        vals, mins = self.vals, self.mins
        vals.pop()  # viz:pop
        mins.pop()

    def top(self) -> int:
        vals = self.vals
        return vals[-1]  # viz:top

    def getMin(self) -> int:
        mins = self.mins
        return mins[-1]  # viz:min
